import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { GuardAvailableFeatureFn, upgradeModalLogic } from 'lib/components/UpgradeModal/upgradeModalLogic'
import { organizationLogic } from 'scenes/organizationLogic'

import { globalModalsLogic } from '~/layout/globalModalsLogic'
import { AvailableFeature, OrganizationType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface newAccountMenuLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    guardAvailableFeature: GuardAvailableFeatureFn // upgradeModalLogic
    isAccountMenuOpen: boolean
    isOrgSwitcherOpen: boolean
    isProjectSwitcherOpen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface newAccountMenuLogicActions {
    showCreateOrganizationModal: () => {
        value: true
    } // globalModalsLogic
    showCreateProjectModal: () => {
        value: true
    } // globalModalsLogic
    closeOrgSwitcher: () => {
        value: true
    }
    closeProjectSwitcher: () => {
        value: true
    }
    createOrganization: () => {
        value: true
    }
    createProject: () => {
        value: true
    }
    openOrgSwitcher: () => {
        value: true
    }
    openProjectSwitcher: () => {
        value: true
    }
    setAccountMenuOpen: (isOpen: boolean) => {
        isOpen: boolean
    }
    toggleAccountMenu: () => {
        value: true
    }
    toggleOrgSwitcher: () => {
        value: true
    }
    toggleProjectSwitcher: () => {
        value: true
    }
}

export type newAccountMenuLogicType = MakeLogicType<newAccountMenuLogicValues, newAccountMenuLogicActions>

export const newAccountMenuLogic = kea<newAccountMenuLogicType>([
    path(['lib', 'components', 'Account', 'accountMenuLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganization'], upgradeModalLogic, ['guardAvailableFeature']],
        actions: [globalModalsLogic, ['showCreateProjectModal', 'showCreateOrganizationModal']],
    })),
    actions({
        setAccountMenuOpen: (isOpen: boolean) => ({ isOpen }),
        toggleAccountMenu: true,
        createProject: true,
        createOrganization: true,
        // Project switcher modal
        openProjectSwitcher: true,
        closeProjectSwitcher: true,
        toggleProjectSwitcher: true,
        // Org switcher modal
        openOrgSwitcher: true,
        closeOrgSwitcher: true,
        toggleOrgSwitcher: true,
    }),
    reducers({
        isAccountMenuOpen: [
            false,
            {
                setAccountMenuOpen: (_, { isOpen }) => isOpen,
                toggleAccountMenu: (state) => !state,
            },
        ],
        isProjectSwitcherOpen: [
            false,
            {
                openProjectSwitcher: () => true,
                closeProjectSwitcher: () => false,
                toggleProjectSwitcher: (state) => !state,
            },
        ],
        isOrgSwitcherOpen: [
            false,
            {
                openOrgSwitcher: () => true,
                closeOrgSwitcher: () => false,
                toggleOrgSwitcher: (state) => !state,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        createProject: () => {
            actions.setAccountMenuOpen(false)
            values.guardAvailableFeature(AvailableFeature.ORGANIZATIONS_PROJECTS, actions.showCreateProjectModal, {
                currentUsage: values.currentOrganization?.teams?.length,
            })
        },
        createOrganization: () => {
            actions.setAccountMenuOpen(false)
            values.guardAvailableFeature(AvailableFeature.ORGANIZATIONS_PROJECTS, actions.showCreateOrganizationModal, {
                guardOnCloud: false,
            })
        },
    })),
])
